const concept=document.body.dataset.concept||'a';
const names={a:'项目工作台',b:'审查收件箱',c:'自动化流程'};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={folder:'<path d="M3 7V5h7l2 3h9v13H3Z"/>',check:'<path d="m5 12 4 4 10-10"/>',review:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-2-14-4 16"/>',plug:'<path d="M8 3v5m8-5v5M5 8h14v3a7 7 0 0 1-14 0Zm7 10v4"/>',bot:'<rect x="4" y="7" width="16" height="13" rx="3"/><path d="M12 7V3m-4 9h.01M16 12h.01M8 16h8"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',external:'<path d="M14 3h7v7m0-7-11 11M10 3H3v18h18v-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 9M20 2v6h-6"/>',branch:'<circle cx="6" cy="4" r="2"/><circle cx="6" cy="20" r="2"/><circle cx="18" cy="4" r="2"/><path d="M6 6v12m12-12v3c0 3-12 3-12 6"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h6"/>'};
const icon=(name,small=false)=>`<svg aria-hidden="true" class="ico${small?' small':''}" viewBox="0 0 24 24">${icons[name]||icons.file}</svg>`;
const btn=(text,action,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const tag=(text,color='')=>`<span class="tag ${color}">${text}</span>`;
const defaultRule='# 通用代码审查\n\n## 必须检查\n1. 检查输入校验、权限边界与错误处理。\n2. 沿调用链检查并发、取消和资源释放。\n3. 检查 API、SDK 与数据迁移的兼容性。\n\n## 证据要求\n每条问题给出文件、行号、触发条件与影响。\n区分确认的问题与待验证的推测。\n测试未执行时记为 NOT_RUN，不能记为通过。\n\n## 审查边界\n只报告本次变更新增的问题。\n缺少原始需求时，不从实现反推验收标准。';
const initial=()=>({connected:true,enabled:concept!=='c',tab:'reports',view:concept==='c'?'wizard':'home',step:0,filter:'all',search:'',selected:'184',head:'98c7c2f',outdated:false,incomplete:false,writeback:'sent',running:false,stage:0,count:1,version:'1.4',reviewVersion:'1.4',draft:defaultRule,rule:defaultRule,hasDraft:false,source:'steer',reviewer:'Code Reviewer',model:'GPT-5.4',effort:'high',project:'Steer',feedback:{},events:['created','updated'],reply:true,build:true,test:true});
let state;try{state={...initial(),...JSON.parse(localStorage.getItem('steer-review-'+concept)||'null'),running:false}}catch{state=initial()}
let modal=null,lastFocus,toastTimer,runTimer;
const persist=()=>localStorage.setItem('steer-review-'+concept,JSON.stringify({...state,running:false}));
const notice=text=>{clearTimeout(toastTimer);$('#toast').innerHTML=`<div class="toast" role="status">${esc(text)}</div>`;toastTimer=setTimeout(()=>$('#toast').innerHTML='',3500)};
const record=()=>state.selected==='184'?{id:'184',title:'飞书默认项目与回复方式配置',repo:'steer',head:state.head}:state.selected==='183'?{id:'183',title:'准备工作区期间持续续租',repo:'relay',head:'20fe146'}:{id:'181',title:'精简会话导航与归档入口',repo:'steer',head:'b5a2a6b'};
const heading=(title,desc,actions='')=>`<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
function sidebar(){const items=concept==='a'?[['folder','项目','project'],['review','自动审查','reports'],['bot','智能体','configure'],['code','Skills','rules'],['plug','集成','connection']]:concept==='b'?[['review','审查收件箱','reports'],['folder','项目范围','configure'],['code','审查规则','rules'],['plug','Codebase 连接','connection']]:[['branch','自动化流程','flows'],['clock','运行记录','reports'],['code','Skills','rules'],['plug','集成','connection']];return `<aside class="sidebar"><div class="brand"><span class="brandmark">S</span>Steer</div><div class="workspace"><span>研发工作区</span>${icon('down',true)}</div><nav class="nav-section" aria-label="工作区导航">${items.map(([i,n,a],j)=>`<button class="nav-item ${j===0?'active':''}" data-action="${a}">${icon(i)}${n}</button>`).join('')}</nav><nav class="nav-section"><span class="nav-label">项目</span>${['Steer','Relay'].map(n=>`<button class="nav-item" data-action="choose-project" data-value="${n}">${icon('folder')}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>${icon('plug',true)} Codebase · ${state.connected?'已连接':'未连接'}</strong>MR 讨论与合并在 Codebase。<br>Steer 负责审查与回写。</div></aside>`}
function render(){persist();$('#app').innerHTML=`<a class="skip" href="#main">跳转到内容</a><header class="prototype-bar"><div class="prototype-left"><a href="index.html" class="title-4">${icon('back',true)} 三方案对比</a>${tag('交互原型','purple')}<span class="muted caption-5">模拟数据 · 不访问真实 Codebase</span></div><div class="actions"><nav class="concept-switch" aria-label="切换方案">${['a','b','c'].map(c=>`<a href="${c}.html" class="${concept===c?'active':''}">${c.toUpperCase()} · ${names[c]}</a>`).join('')}</nav>${btn('重置','reset','ghost small')}</div></header><div class="shell">${sidebar()}<main class="main" id="main"><header class="topline"><div class="crumb"><span>研发工作区</span><span>/</span><strong>${names[concept]}</strong>${concept==='a'?`<span>/</span><strong>${state.project}</strong>`:''}</div><div class="actions">${btn('模拟事件','scenarios','ghost small')}${btn(`${icon('plug',true)} ${state.connected?'Codebase 已连接':'连接 Codebase'}`,'connection','small')}<span class="avatar">KD</span></div></header>${content()}</main></div><div id="modal-root"></div><div id="toast"></div>`;if(modal)renderModal()}
function content(){if(state.view==='settings')return `<div class="page">${heading('审查配置','规范交给 Skill，触发与回写由项目策略控制。',btn('保存配置','save-config','primary'))}${config()}</div>`;if(state.view==='report'&&concept!=='b')return `<div class="page">${btn(`${icon('back',true)} 返回${concept==='a'?'项目审查':'运行记录'}`,'back','ghost small')}<div class="space-24">${report()}</div></div>`;return concept==='a'?project():concept==='b'?inbox():workflow()}
function rows(compact=false){let list=[['184','飞书默认项目与回复方式配置','steer','2 个问题 · 11 分钟前','需要处理','red'],['183','准备工作区期间持续续租','relay','完整 race 检查未执行 · 昨天 17:42','证据不足','amber'],['181','精简会话导航与归档入口','steer','0 个阻断问题 · 昨天 15:08','无阻断问题','green']];if(!compact&&concept==='a'&&state.view==='home')list=list.filter(r=>r[2]===state.project.toLowerCase());list=list.filter(r=>(state.filter==='all'||state.filter===r[5])&&r.join(' ').toLowerCase().includes(state.search.toLowerCase()));if(!list.length)return `<div class="empty"><h3>没有匹配的审查</h3><p class="muted">尝试其他关键词。</p>${btn('清除筛选','clear-filter','small')}</div>`;return list.map(([id,title,repo,meta,status,color])=>{if(id==='184'&&state.outdated){status='报告已过期';color='amber'}if(id===state.selected&&state.running){status='正在审查';color='purple';meta='演示任务 · 正在执行'}return `<button class="item-row ${compact&&state.selected===id?'active':''}" data-action="review" data-id="${id}">${compact?'':`<span class="row-icon">${icon('branch')}</span>`}<div class="grow"><span class="caption-5 muted">${repo} · MR !${id}</span><h3>${title}</h3><p>${meta}</p></div>${tag(status,color)}${compact?'':icon('arrow',true)}</button>`}).join('')}
function project(){return `<div class="page">${heading(`${state.project} · 自动审查`,'项目内配置，审查结果同步回 Codebase 的 MR。',btn(`${icon('plus',true)} 手动审查`,'manual','primary'))}<div class="tabs" role="tablist">${[['reports','审查报告'],['config','审查配置']].map(([k,n])=>`<button class="tab ${state.tab===k?'active':''}" role="tab" aria-selected="${state.tab===k}" data-action="tab" data-value="${k}">${n}</button>`).join('')}</div>${state.tab==='config'?config():`${progress()}<div class="stats"><div class="stat"><span class="caption-5">最近 7 天 · 演示数据</span><strong>23</strong><span class="caption-5">审查已完成</span></div><div class="stat"><span class="caption-5">需要处理</span><strong>4</strong><span class="caption-5">包含可定位的问题</span></div><div class="stat"><span class="caption-5">平均耗时</span><strong>2m 18s</strong><span class="caption-5">最近 7 天</span></div></div><div class="grid-2"><section class="section"><header class="section-head"><h3>最近的 MR 审查</h3>${tag('由 Codebase 自动触发')}</header>${rows()}</section><aside><section class="section"><header class="section-head"><h3>当前配置</h3>${btn('编辑','configure','link')}</header><div class="section-body">${summary()}<div class="note space-24">只提交报告，不自动批准或合并 MR。</div></div></section><section class="section"><div class="section-body"><h3>规范与策略各司其职</h3><p class="muted caption-5 space-16">Skill 定义检查内容与证据要求。项目配置决定触发事件、必要检查和回写方式。</p>${btn('维护 Review Skill','rules','link')}</div></section></aside></div>`}</div>`}
function summary(){return `<div class="dl"><div class="dl-line"><span>自动审查</span>${tag(state.enabled?'已开启':'未开启',state.enabled?'green':'')}</div><div class="dl-line"><span>Reviewer</span><span>${esc(state.reviewer)}</span></div><div class="dl-line"><span>模型 / Effort</span><span>${esc(state.model)} / ${state.effort}</span></div><div class="dl-line"><span>审查规范</span>${btn(`3 个 Skill · v${state.version}`,'rules','link')}</div><div class="dl-line"><span>回写方式</span><span>${state.reply?'MR 汇总评论':'仅保存在 Steer'}</span></div></div>`}
function rules(){return `<div class="rule-list">${[['通用代码审查','工作区规范',state.version],['Go 并发与资源释放','语言规范','2.1'],[`${state.project} 架构与兼容性`,'项目规范','1.2']].map(([n,t,v],i)=>`<div class="rule-row">${icon('file')}<div><strong class="title-4">${n}</strong><span class="muted">${t} · ${i===0&&state.source==='repo'?'仓库同步 · main':'Steer 维护'}</span></div>${tag('v'+v)}${btn('查看','rules','ghost small',`data-rule="${i}"`)}</div>`).join('')}</div>`}
function check(name,title,desc='',checked=true){return `<label class="check-row"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${title}${desc?`<small>${desc}</small>`:''}</span></label>`}
function config(){return `<form id="config-form"><div class="grid-2"><section class="section"><div class="section-body"><div class="form-section"><h3>项目与 Reviewer</h3><div class="form-grid"><label class="field">Codebase 仓库<select name="project">${['Steer','Relay'].map(v=>`<option ${v===state.project?'selected':''}>${v}</option>`).join('')}</select><small>项目与仓库绑定，使用机器人访问权限。</small></label><label class="field">Reviewer Agent<select name="reviewer">${['Code Reviewer','架构审查员'].map(v=>`<option ${v===state.reviewer?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">模型<select name="model">${['GPT-5.4','Claude Sonnet 4.6'].map(v=>`<option ${v===state.model?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Effort<select name="effort">${['medium','high','xhigh'].map(v=>`<option ${v===state.effort?'selected':''}>${v}</option>`).join('')}</select></label></div></div><div class="form-section"><div class="flex" style="justify-content:space-between"><h3>审查规范 · Review Skills</h3>${btn('维护规范','rules','link')}</div>${rules()}<p class="muted caption-5 space-16">每次审查固定规范版本；修改规则不会改变历史报告。</p></div><div class="form-section"><h3>触发与必要检查</h3>${check('enabled','开启自动审查','从 Codebase 接收事件，创建独立 Review 任务。',state.enabled)}<div class="form-grid">${check('created','MR 创建','',state.events.includes('created'))}${check('updated','MR 有新提交','',state.events.includes('updated'))}${check('build','读取构建检查结果','',state.build)}${check('test','读取测试检查结果','',state.test)}</div></div><div class="form-section"><h3>结果回写</h3>${check('reply','更新 MR 汇总评论','同一 MR 更新一条评论，避免重复通知。',state.reply)}<div class="note">批准、讨论处理和合并继续在 Codebase 管理。</div></div><div class="error" id="config-error"></div><div class="actions">${btn('保存配置','save-config','primary')}${btn('发送测试 MR 事件','test-event')}</div></div></section><aside><section class="section"><header class="section-head"><h3>流程预览</h3></header><div class="section-body">${timeline()}<div class="note space-24">缺少必要检查时，结果是“证据不足”，不会记为通过。</div></div></section></aside></div></form>`}
function timeline(){return `<div class="timeline">${[['接收 Codebase MR 事件','固定目标分支与提交版本'],['准备独立工作区','不使用开发中的可变目录'],['执行 Reviewer + Skills','保留问题位置和证据'],['校验报告并回写 MR','重复事件复用已有任务']].map(([n,d],i)=>`<div class="timeline-item"><span class="node">${i+1}</span><div><strong class="title-4">${n}</strong><p>${d}</p></div></div>`).join('')}</div>`}
function inbox(){return `<div class="inbox-layout"><aside class="inbox-list"><div class="section-head"><h3>审查收件箱</h3>${tag('3')}</div><label><span class="caption-5 muted">搜索 MR 或项目</span><input class="search" id="review-search" placeholder="项目、MR 标题…" value="${esc(state.search)}"></label><div class="filter-group">${[['all','全部'],['red','需处理'],['amber','证据不足'],['green','无阻断']].map(([v,n])=>`<button class="filter ${state.filter===v?'active':''}" data-action="filter" data-value="${v}">${n}</button>`).join('')}</div><div id="inbox-rows">${rows(true)}</div><div class="space-24">${btn(`${icon('plus',true)} 手动审查`,'manual','full')}</div></aside><div class="inbox-content">${report()}</div></div>`}
function progress(){return state.running?`<div class="run-strip" role="status"><div><strong class="title-4">MR !${state.selected} · 正在审查</strong><div class="run-progress space-16">${['接收事件','准备代码','Agent 审查','校验与回写'].map((s,i)=>`<span class="${i===state.stage?'current':''}">${i<state.stage?'✓ ':''}${s}</span>${i<3?icon('arrow',true):''}`).join('')}</div></div>${tag('演示任务','purple')}</div>`:''}
function findings(){const relay=state.selected==='183',list=relay?[['取消后仍可能等待仓库锁','node/worker.go:218','取消信号未传递到锁等待时，同一仓库的慢任务可能占住执行槽位。','检查 context 是否贯穿目录准备，并补充取消锁等待用例。']]:[['项目查询需要校验 Workspace 归属','server/internal/api/integrations.go:46','只校验项目存在而不校验所属 Workspace 时，指定其他工作区项目可能使用错误的执行目录。','沿查询路径确认 Workspace 条件，增加跨工作区项目的拒绝用例。'],['取消后仍可能追加最终回复','server/internal/api/feishu.go:954','取消与消息追加同时发生时，需要确认上下文失效后不会继续写入旧任务。','补充取消与追加的并发验证；本条尚未通过运行复现。']];return list.map(([t,path,desc,fix],i)=>`<details class="finding" ${i===0?'open':''}><summary>${tag(i===0?'中等':'待验证',i===0?'red':'amber')}<div><strong class="title-4">${t}</strong><p class="mono">${path}</p></div>${icon('down',true)}</summary><div class="finding-body"><p>${desc}</p><div class="codebox"><div class="path">${path} · 演示片段</div><pre>${relay?'218  lock.Lock()\n219  workspace.Prepare(ctx)':i===0?'<span class="removed">46  project, err := store.Project(ctx, projectID)</span><span class="added">46  project, err := store.Project(ctx, workspaceID, projectID)</span>47  if err != nil { return err }':'954  if content != "" {\n955      stream.Append(ctx, content)\n956  }'}</pre></div><p class="muted">建议：${fix}</p><div class="feedback"><span class="caption-5 muted">这条问题有帮助吗？</span>${btn(state.feedback['f'+i]==='accepted'?'已认可':'认可','feedback','small',`data-id="f${i}" data-value="accepted"`)}${btn(state.feedback['f'+i]==='false-positive'?'已标为误报':'误报','feedback','ghost small',`data-id="f${i}" data-value="false-positive"`)}</div></div></details>`).join('')}
function report(){const r=record(),missing=state.incomplete||r.id==='183',good=r.id==='181',old=state.outdated&&r.id==='184';if(state.running)return `${heading(`MR !${r.id} · ${r.title}`,'正在审查固定提交版本，完成后生成报告。')}${progress()}<section class="section"><div class="section-body"><h3>Reviewer 正在检查代码与规范</h3><p class="muted space-16">报告尚未完成。旧报告不会作为本次提交的审查结论。</p><div class="skeleton space-24"></div><div class="skeleton short"></div><div class="skeleton"></div></div></section>`;return `${heading(`MR !${r.id} · ${r.title}`,`KDF5000 / ${r.repo} · feat/review → main`,btn(`${icon('external',true)} 在 Codebase 查看`,'codebase'))}<div class="report-meta"><span class="mono">${r.head} ← 09f887a</span><span>审查 #${state.count} · 规范 v${state.reviewVersion}</span><span>2 分 18 秒 · 演示数据</span></div>${progress()}${old?`<div class="note amber">MR 已更新到 7a8b9c0，旧报告只对应 ${r.head}。${btn('审查最新提交','rerun','link')}</div>`:''}<div class="report-hero ${good?'good':''} space-24">${tag(old?'报告已过期':missing?'证据不足':good?'未发现阻断问题':'需要处理',old||missing?'amber':good?'green':'red')}<h2>${good?'未发现本次变更新增的阻断问题':missing?'必要检查尚未完成':'发现 2 个需要处理的问题'}</h2><p>${good?'审查范围内未发现阻断问题，最终审批与合并仍在 Codebase。':missing?'完整 race 检查未执行，不能将本次审查记为通过。':'工作区访问边界与取消处理需要确认。下方提供具体代码位置和触发条件。'}</p></div><div class="grid-2"><div><section class="section"><header class="section-head"><h3>${good?'审查摘要':'问题与证据'}</h3>${tag('固定提交版本')}</header><div class="section-body">${good?'<p class="muted">会话排序只由最新消息时间决定。已检查查看、重命名与置顶操作的调用链。</p>':findings()}<div class="note space-16">反馈只用于改善审查质量，不会自动解决 Codebase 中的讨论。</div></div></section><section class="section"><header class="section-head"><h3>检查结果</h3>${tag('演示检查')}</header><div class="section-body"><div class="summary-line"><span>独立构建</span>${tag('通过','green')}</div><div class="summary-line"><span>任务与权限测试</span>${tag('通过','green')}</div><div class="summary-line"><span>完整 race 检查</span>${tag(missing?'未执行':'通过',missing?'amber':'green')}</div></div></section></div><aside><section class="section"><header class="section-head"><h3>回写 Codebase</h3>${tag(state.writeback==='failed'?'回写失败':state.writeback==='pending'?'待回写':'已回写',state.writeback==='failed'?'red':state.writeback==='pending'?'amber':'green')}</header><div class="section-body"><p class="muted caption-5">由 Steer Review Bot 发布。后续审查更新同一条 MR 汇总评论。</p>${state.writeback==='failed'?'<div class="note red space-16">评论发布失败，报告已保存在 Steer。</div>':''}<div class="space-16">${state.writeback==='sent'?btn('查看 MR 评论预览','codebase','full'):btn(state.writeback==='failed'?'重试回写':'回写报告','retry','primary full')}</div></div></section><section class="section"><header class="section-head"><h3>本次执行</h3></header><div class="section-body">${timeline()}<div class="divider"></div>${btn('查看本次规范','snapshot','link')}<div class="space-16">${btn(`${icon('refresh',true)} 重新审查`,'rerun','full',state.running?'disabled':'')}</div></div></section></aside></div>`}
function workflow(){if(state.view==='flows')return `<div class="page">${heading('自动化流程','以事件为起点，配置一次，持续生成审查报告。',btn(`${icon('plus',true)} 创建流程`,'new-flow','primary'))}<article class="recipe"><div>${tag(state.enabled?'已启用':'草稿',state.enabled?'green':'')}<h3>${state.project} · MR 自动审查</h3><p>MR 创建或更新后，由 ${esc(state.reviewer)} 生成报告并回写评论。</p><div class="chain"><span>Codebase</span>${icon('arrow',true)}<span>Reviewer + 3 个 Skill</span>${icon('arrow',true)}<span>MR 汇总报告</span></div></div><div class="recipe-actions">${btn('编辑流程','new-flow')}${btn('测试运行','test-event','primary')}</div></article><section class="section"><header class="section-head"><h3>最近运行</h3></header>${rows()}</section></div>`;if(state.view==='runs')return `<div class="page">${heading('运行记录','查看事件、任务与回写过程。',btn('返回流程','flows'))}${progress()}<section class="section"><header class="section-head"><h3>最近审查</h3></header>${rows()}</section></div>`;const steps=['接入 Codebase','选择范围','配置审查','结果回写'];return `<div class="page">${heading('建立 MR 自动审查流程','按事件、范围、审查和回写四步配置。每一步都能独立调整。',btn('查看已有流程','flows'))}<div class="workflow-map" aria-label="配置步骤">${steps.map((n,i)=>`<button class="flow-node ${state.step===i?'active':i<state.step?'done':''}" data-action="step" data-value="${i}" aria-current="${state.step===i?'step':'false'}"><span class="num">${i<state.step?'✓':i+1}</span><h3>${n}</h3><p>${['机器人身份与事件','项目和触发条件','Reviewer 与 Skills','评论与报告策略'][i]}</p></button>${i<3?'<span class="flow-edge"></span>':''}`).join('')}</div><div class="wizard-body"><section class="section"><div class="section-body"><div class="step-heading"><h2>${steps[state.step]}</h2>${tag(`第 ${state.step+1} / 4 步`,'purple')}</div>${wizardStep()}<div id="wizard-error" class="error"></div><div class="divider"></div><div class="flex" style="justify-content:space-between">${btn('上一步','prev','ghost',state.step===0?'disabled':'')}${btn(state.step===3?'启用并测试流程':'下一步','next','primary')}</div></div></section><aside><section class="section"><header class="section-head"><h3>这个流程将如何运行</h3></header><div class="section-body">${summary()}<div class="note space-24">规则发布只影响新审查。不会自动批准或合并 MR。</div></div></section></aside></div></div>`}
function wizardStep(){if(state.step===0)return `<div class="rule-row">${icon('plug')}<div><strong class="title-4">Codebase</strong><span class="muted">code.byted.org · Steer Review Bot</span></div>${tag(state.connected?'已连接':'未连接',state.connected?'green':'amber')}${btn('查看连接','connection','small')}</div><div class="note space-24">接收 MR 事件，读取源码与 diff，回写审查汇总。连接测试均为模拟。</div><div class="space-24"><strong class="title-4">事件入口</strong><div class="codebox"><pre>https://steer.example/api/integrations/codebase/events</pre></div><p class="muted caption-5">正式接入前需确认 Codebase 的事件与 API 能力。</p></div>`;if(state.step===1)return `<form id="wizard-form"><label class="field">项目<select name="project">${['Steer','Relay'].map(v=>`<option ${state.project===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="form-grid">${check('created','MR 创建','',state.events.includes('created'))}${check('updated','MR 有新提交','',state.events.includes('updated'))}</div><div class="note space-24">新提交使旧报告过期，每份报告固定 base / head。</div></form>`;if(state.step===2)return `<form id="wizard-form"><div class="form-grid"><label class="field">Reviewer<select name="reviewer">${['Code Reviewer','架构审查员'].map(v=>`<option ${state.reviewer===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">模型<select name="model">${['GPT-5.4','Claude Sonnet 4.6'].map(v=>`<option ${state.model===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Effort<select name="effort">${['medium','high','xhigh'].map(v=>`<option ${state.effort===v?'selected':''}>${v}</option>`).join('')}</select></label></div></form><div class="space-24">${rules()}</div>${btn('编辑并发布 Review Skill','rules','link')}<div class="note space-16">Skill 定义检查内容，报告格式由系统校验。</div>`;return `<form id="wizard-form">${check('reply','回写 MR 汇总评论','后续审查更新同一条评论。',state.reply)}<div class="summary-line"><span>自动批准 / 合并</span>${tag('未启用')}</div><div class="summary-line"><span>必要检查缺失</span>${tag('证据不足','amber')}</div><div class="summary-line"><span>回写失败</span><span class="caption-5 muted">保留报告，允许重试</span></div><div class="note space-24">启用后发送一条模拟 MR 事件，确认完整流程。</div></form>`}
function open(type){lastFocus=document.activeElement;modal=type;renderModal();requestAnimationFrame(()=>$('#modal-root [autofocus]')?.focus()||$('#modal-root button')?.focus())}
function close(){modal=null;$('#modal-root').innerHTML='';lastFocus?.focus()}
function frame(title,desc,body,footer='',wide=false){return `<div class="overlay" data-overlay="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${desc}</p></div><button class="icon-btn" aria-label="关闭" data-action="close">${icon('close')}</button></header><div class="modal-content">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`}
function renderModal(){let html='';if(modal==='connection')html=frame('连接 Codebase','模拟验证，不向真实平台发送凭据。',`<form id="connection-form"><div class="form-grid"><label class="field full">Codebase 地址<input type="url" name="url" value="https://code.byted.org" autofocus></label><label class="field full">机器人凭据<input name="token" type="password" value="demo-token" autocomplete="off"><small>演示凭据，不会保存到浏览器。</small></label></div><div class="space-24"><h3>能力检查</h3>${['读取仓库与 MR','接收 MR 事件','发布汇总评论'].map(n=>`<div class="summary-line"><span>${n}</span>${tag(state.connected?'已验证':'待验证',state.connected?'green':'')}</div>`).join('')}</div><div class="error" id="connection-error"></div></form>`,`<span>身份：Steer Review Bot</span><div class="actions">${btn('取消','close','ghost')}${btn('验证连接','verify','primary')}</div>`);
if(modal==='rules')html=frame('Review Skill · 通用代码审查',`已发布 v${state.version} · ${state.hasDraft?'有未发布草稿':'无未发布修改'}`,`<div class="source-switch"><label><input type="radio" name="source" value="steer" ${state.source==='steer'?'checked':''}>在 Steer 维护</label><label><input type="radio" name="source" value="repo" ${state.source==='repo'?'checked':''}>从仓库同步</label></div><div class="note">${state.source==='repo'?'来源：Codebase / steer / main / review/SKILL.md。仓库是权威来源，先在 Codebase 提交 MR，再同步。':'保存为草稿，发布后才用于新审查。历史报告保留原规范版本。'}</div><label class="field space-16">审查规范内容<textarea id="rule-editor" ${state.source==='repo'?'readonly':''}>${esc(state.draft)}</textarea></label><div class="error" id="rule-error"></div>`,`<span>通用规范 · v${state.version}</span><div class="actions">${btn('取消','close','ghost')}${state.source==='repo'?btn('同步仓库版本','sync-rule','primary'):btn('保存草稿','save-draft')}${state.source==='steer'?btn('发布版本','publish-confirm','primary'):''}</div>`,true);
if(modal==='snapshot')html=frame('本次审查使用的规范',`审查 #${state.count} · 固定版本 v${state.reviewVersion}`,`<div class="note">这是本次执行的规范快照。最新发布版本 v${state.version} 不会改变这份历史报告。</div><label class="field space-16">通用代码审查 · v${state.reviewVersion}<textarea readonly>${esc(state.reviewRule||defaultRule)}</textarea></label>`,`<span>只读版本快照</span>${btn('关闭','close')}`,true);
if(modal==='publish')html=frame('发布 Review Skill','新审查使用新版本，正在执行的任务和历史报告保持不变。',`<div class="dl"><div class="dl-line"><span>规范</span><span>通用代码审查</span></div><div class="dl-line"><span>版本</span><span class="mono">v${state.version} → v${nextVersion()}</span></div><div class="dl-line"><span>适用范围</span><span>Steer / Relay · 新审查</span></div></div>`,`<span>确认后创建不可变的已发布版本</span><div class="actions">${btn('返回编辑','rules','ghost')}${btn('确认发布','publish','primary')}</div>`);
if(modal==='manual')html=frame('手动发起审查','从 Codebase MR 开始，固定代码版本。',`<form id="manual-form"><label class="field">MR 链接<input name="mr" value="https://code.byted.org/KDF5000/steer/merge_requests/184" autofocus><small>支持演示 MR !184、!183 和 !181。</small></label><div class="rule-row space-24">${icon('bot')}<div><strong class="title-4">${esc(state.reviewer)}</strong><span class="muted">${esc(state.model)} · ${state.effort} · 3 个 Skill</span></div>${tag('v'+state.version)}</div><div class="error" id="manual-error"></div></form>`,`<span>生成报告，按项目策略回写 MR</span><div class="actions">${btn('取消','close','ghost')}${btn('开始审查','start','primary')}</div>`);
if(modal==='scenarios')html=frame('模拟事件与异常','三套方案可以体验相同的正常和异常流程。',`<div class="rule-list">${[['new-commit','MR 有新提交','旧报告过期，审查最新提交'],['missing','必要检查未执行','显示证据不足，不记为通过'],['writeback-fail','Codebase 回写失败','保留报告，重试不重复执行'],['duplicate','同一事件重复到达','复用已有任务'],['disconnect','连接凭据失效','修复连接后重试验证']].map(([a,n,d])=>`<button class="item-row" data-action="${a}"><span class="row-icon">${icon('branch')}</span><div class="grow"><h3>${n}</h3><p>${d}</p></div>${icon('arrow',true)}</button>`).join('')}</div>`);
if(modal==='codebase'){const r=record(),missing=state.incomplete||r.id==='183';html=frame('Codebase · MR 评论预览','模拟回写效果，讨论、批准与合并仍在 Codebase。',`<div class="codebase-header"><div class="crumb">KDF5000 / ${r.repo} / Merge requests / !${r.id}</div><h3 class="space-16">${r.title}</h3><div class="meta space-16">${tag('Open','green')}<span class="caption-5 muted">feat/review → main</span></div></div><div class="comment"><header><span class="row-icon">${icon('bot')}</span><strong class="title-4">Steer Review Bot</strong><span class="caption-5 muted">更新同一条评论 · 演示</span></header><article><h3>自动代码审查 · ${state.outdated?'报告已过期':missing?'证据不足':r.id==='181'?'未发现阻断问题':'需要处理'}</h3><p class="mono">提交 ${r.head} · 规范 v${state.reviewVersion}</p>${state.outdated?'<div class="note amber">MR 已有新提交，以下报告只适用于旧版本。</div>':r.id==='181'?'<p>审查范围内未发现变更新增的阻断问题。</p>':'<ol class="comment-list"><li>工作区或任务取消边界需要确认。</li><li>检查对应测试结果与运行证据。</li></ol>'}<p class="muted space-16">${missing?'完整 race 检查未执行，不能标为通过。':'构建和任务测试通过（原型模拟）。'}</p>${btn('查看 Steer 完整报告','return-report','link')}</article></div>`,`<span>此处不提供批准与合并操作</span>${btn('返回 Steer','close','primary')}`,true)}
$('#modal-root').innerHTML=html}
const nextVersion=()=>`1.${Number(state.version.split('.')[1])+1}`;
function saveConfig(){const d=new FormData($('#config-form'));if(d.has('enabled')&&!state.connected){$('#config-error').textContent='请先验证 Codebase 连接。';return}const events=['created','updated'].filter(x=>d.has(x));if(d.has('enabled')&&!events.length){$('#config-error').textContent='开启自动审查时至少选择一种 MR 事件。';return}['project','reviewer','model','effort'].forEach(k=>state[k]=d.get(k));['enabled','reply','build','test'].forEach(k=>state[k]=d.has(k));state.events=events;render();notice('项目审查配置已保存（模拟）。')}
function readStep(){if(state.step===0)return true;const f=$('#wizard-form');if(!f)return true;const d=new FormData(f);if(state.step===1){state.project=d.get('project');state.events=['created','updated'].filter(x=>d.has(x));if(!state.events.length){$('#wizard-error').textContent='至少选择一种 MR 事件。';return false}}if(state.step===2){state.reviewer=d.get('reviewer');state.model=d.get('model');state.effort=d.get('effort')}if(state.step===3)state.reply=d.has('reply');return true}
function run(id=state.selected){if(state.running){notice('已有审查任务正在执行。');return}if(!state.connected){open('connection');$('#connection-error').textContent='连接不可用，请重新验证。';return}state.selected=id;state.running=true;state.stage=0;state.reviewVersion=state.version;state.reviewRule=state.rule;state.writeback='pending';state.view=concept==='c'?'runs':concept==='b'?'home':'report';render();let s=0;runTimer=setInterval(()=>{s++;if(s<4){state.stage=s;render()}else{clearInterval(runTimer);state.running=false;state.count++;if(state.outdated)state.head='7a8b9c0';state.outdated=false;state.incomplete=false;state.writeback=state.reply?'sent':'pending';render();notice(state.reply?'审查完成，MR 汇总评论已更新（模拟）。':'审查完成，报告保存在 Steer（模拟）。')}},700)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el){if(e.target.dataset.overlay)close();return}const a=el.dataset.action;
if(a==='close'){close();return}if(a==='reset'){clearInterval(runTimer);state=initial();modal=null;render();notice('当前方案已重置。');return}
if(a==='rules'&&Number(el.dataset.rule)>0){const language=el.dataset.rule==='1';lastFocus=document.activeElement;modal='rule-detail';$('#modal-root').innerHTML=frame(language?'Review Skill · Go 并发与资源释放':`Review Skill · ${state.project} 架构与兼容性`,'已发布规范 · 只读预览',`<div class="note">在项目中绑定此规范后，Reviewer 会与通用规则一起执行。</div><label class="field space-16">规范内容<textarea readonly>${language?'# Go 并发与资源释放\n\n检查 context 取消是否贯穿调用链。\n检查 goroutine 退出、锁粒度与资源释放。\n检查共享状态的数据竞争与 race 验证。':'# '+state.project+' 架构与兼容性\n\n检查 API 与 SDK 版本兼容。\n检查数据库迁移与滚动部署顺序。\n独立构建必须使用已发布的依赖，不能依赖本地 go.work。'}</textarea></label>`,`<span>项目已绑定</span>${btn('关闭','close')}`,true);return}
if(['connection','rules','manual','scenarios','codebase','snapshot'].includes(a)){open(a);return}
if(a==='verify'){const d=new FormData($('#connection-form'));let valid=false;try{valid=/^https?:$/.test(new URL(d.get('url')).protocol)&&!!d.get('token').trim()}catch{}if(!valid){$('#connection-error').textContent='请输入有效地址与机器人凭据。';return}if(state.failConnection){state.failConnection=false;persist();$('#connection-error').textContent='凭据验证失败（模拟）。请检查权限，再次验证。';return}el.disabled=true;el.textContent='验证中…';setTimeout(()=>{state.connected=true;close();render();notice('读取仓库、接收事件与评论回写已验证（模拟）。')},600);return}
if(a==='save-draft'||a==='publish-confirm'){const text=$('#rule-editor').value.trim();if(!text){$('#rule-error').textContent='规范内容不能为空。';return}state.draft=text;state.hasDraft=true;persist();if(a==='save-draft'){close();render();notice('草稿已保存，正式审查仍使用已发布版本。')}else{modal='publish';renderModal()}return}
if(a==='publish'||a==='sync-rule'){state.rule=state.draft;state.version=nextVersion();state.hasDraft=false;close();render();notice(a==='publish'?`Review Skill v${state.version} 已发布，仅影响新审查。`:'已从 main 同步并固定规范版本（模拟）。');return}
if(a==='start'){const value=new FormData($('#manual-form')).get('mr'),m=String(value).match(/^https?:\/\/[^/]+\/[^\s]+\/merge_requests\/(184|183|181)\/?$/);if(!m){$('#manual-error').textContent='请输入演示 MR !184、!183 或 !181 的有效链接。';return}close();run(m[1]);return}
if(a==='configure'){state.view='settings';render();return}if(a==='save-config'){saveConfig();return}if(a==='tab'){state.tab=el.dataset.value;state.view='home';render();return}
if(a==='project'||a==='choose-project'){if(el.dataset.value)state.project=el.dataset.value;state.view=concept==='a'?'home':'settings';render();return}
if(a==='review'){state.selected=el.dataset.id;state.view='report';render();return}if(a==='filter'){state.filter=el.dataset.value;render();return}if(a==='clear-filter'){state.filter='all';state.search='';render();return}
if(a==='feedback'){state.feedback[el.dataset.id]=el.dataset.value;render();notice('反馈已记录，Codebase 讨论状态不变。');return}
if(a==='return-report'){close();state.view='report';render();return}if(a==='retry'){if(!state.connected){open('connection');return}state.writeback='sent';render();notice('原 MR 评论已更新，未重复创建审查任务（模拟）。');return}
if(['new-commit','missing','writeback-fail'].includes(a)){close();state.selected='184';state.view='report';if(a==='new-commit')state.outdated=true;if(a==='missing')state.incomplete=true;if(a==='writeback-fail')state.writeback='failed';render();return}
if(a==='duplicate'){close();notice('该事件已处理，复用已有任务，未重复执行。');return}if(a==='disconnect'){close();state.connected=false;state.failConnection=true;render();open('connection');return}
if(a==='rerun'||a==='test-event'){close();run();return}if(a==='back'){state.view=concept==='c'?'runs':'home';render();return}if(a==='reports'){state.view=concept==='c'?'runs':'home';state.tab='reports';render();return}
if(a==='flows'){state.view='flows';render();return}if(a==='new-flow'){state.view='wizard';state.step=0;render();return}
if(a==='step'){if(!readStep())return;state.step=Number(el.dataset.value);render();return}if(a==='prev'){if(!readStep())return;state.step=Math.max(0,state.step-1);render();return}
if(a==='next'){if(state.step===0&&!state.connected){$('#wizard-error').textContent='先验证 Codebase 连接。';return}if(!readStep())return;if(state.step<3){state.step++;render()}else{state.enabled=true;run('184')}return}
});
document.addEventListener('input',e=>{if(e.target.id==='review-search'){state.search=e.target.value;persist();$('#inbox-rows').innerHTML=rows(true)}if(e.target.id==='rule-editor')state.draft=e.target.value});
document.addEventListener('change',e=>{if(e.target.name==='source'){state.source=e.target.value;persist();renderModal()}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const f=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,select,textarea')];if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.prototype={get state(){return state},reset(){clearInterval(runTimer);state=initial();modal=null;render()}};
render();
